INSERT INTO produtos (id, categoria_id, marca, nome, volume, teor_alcool, origem, preco, preco_antigo, selo, destaque, imagem_id, lacre_y, lacre_largura, descricao, notas, ordem) VALUES
  ('jw-black', 'whisky', 'Johnnie Walker', 'Black Label 12 anos', '750 ml', 40, 'Escócia', 99.90, 119.90, 'Mais vendido', TRUE, 1, 0.18, 0.15, 'Blend de whiskies envelhecidos por no mínimo 12 anos. Encorpado e equilibrado, com fumaça suave, baunilha e frutas escuras.', '["Defumado suave","Baunilha","Frutas escuras"]', 1),
  ('jack-7', 'whisky', 'Jack Daniel''s', 'Old No.7', '1 L', 40, 'EUA (Tennessee)', 129.90, 189.90, NULL, TRUE, 2, 0.097, 0.13, 'O Tennessee whiskey mais famoso do mundo, filtrado gota a gota em carvão de bordo. Macio, com caramelo, baunilha e carvalho tostado.', '["Caramelo","Baunilha","Carvalho tostado"]', 2),
  ('jack-apple', 'whisky', 'Jack Daniel''s', 'Tennessee Apple', '1 L', 35, 'EUA (Tennessee)', 139.90, NULL, NULL, TRUE, 3, 0.116, 0.14, 'Licor de maçã verde com Jack Daniel’s Old No.7. Fresco e frutado, vai muito bem com gelo ou com tônica.', '["Maçã verde","Caramelo","Refrescante"]', 3),
  ('jack-fire', 'whisky', 'Jack Daniel''s', 'Tennessee Fire', '1 L', 35, 'EUA (Tennessee)', 139.90, NULL, NULL, FALSE, 4, 0.116, 0.13, 'Licor de canela picante com Jack Daniel’s Old No.7. Aquece na medida — perfeito em shot gelado.', '["Canela","Especiarias","Final quente"]', 4),
  ('absolut-1l', 'vodka', 'Absolut', 'Vodka', '1 L', 40, 'Suécia', 74.90, 89.90, 'Mais vendido', TRUE, 5, 0.073, 0.12, 'Vodka sueca feita com trigo de inverno e água de Åhus. Limpa e encorpada, base perfeita para qualquer drink.', '["Limpa","Trigo","Final seco"]', 5),
  ('absolut-750', 'vodka', 'Absolut', 'Vodka', '750 ml', 40, 'Suécia', 69.90, NULL, NULL, FALSE, 6, 0.071, 0.12, 'A mesma Absolut original na garrafa de 750 ml. Destilada continuamente, sem açúcar adicionado.', '["Limpa","Trigo","Versátil"]', 6),
  ('absolut-tabasco', 'vodka', 'Absolut', 'Tabasco', '750 ml', 38, 'Suécia', 99.90, NULL, 'Novidade', FALSE, 7, 0.08, 0.13, 'Vodka saborizada com a pimenta Tabasco: picância na medida, ótima para Bloody Mary e shots.', '["Pimenta","Picante","Bloody Mary"]', 7),
  ('skyy', 'vodka', 'Skyy', 'Vodka', '980 ml', 40, 'EUA', 34.90, 46.90, NULL, FALSE, 8, 0.06, 0.13, 'Vodka americana destilada quatro vezes e filtrada três vezes. Suave e limpa, na icônica garrafa azul.', '["Suave","Limpa","Garrafa azul"]', 8),
  ('smirnoff', 'vodka', 'Smirnoff', 'Nº 21', '998 ml', 37.5, 'Brasil', 37.90, 46.90, NULL, TRUE, 9, 0.203, 0.15, 'A receita Nº 21, filtrada dez vezes. Neutra e macia — a vodka mais vendida do mundo.', '["Neutra","Macia","Dez vezes filtrada"]', 9),
  ('orloff', 'vodka', 'Orloff', 'Vodka', '1 L', 37.5, 'Brasil', 29.90, NULL, NULL, FALSE, 10, 0.198, 0.15, 'Vodka cinco vezes destilada, de sabor leve. Ótimo custo-benefício para caipiroska e drinks de festa.', '["Leve","5x destilada","Caipiroska"]', 10),
  ('tanqueray', 'gin', 'Tanqueray', 'London Dry', '750 ml', 47.3, 'Reino Unido', 94.90, 109.90, 'Favorito do gin tônica', TRUE, 11, 0.173, 0.14, 'Versão Export Strength, com quatro botânicos — zimbro, coentro, angélica e alcaçuz — destilados quatro vezes. Seco e marcante, o gin do gin tônica clássico.', '["Zimbro","Cítrico","Seco"]', 11),
  ('bombay', 'gin', 'Bombay', 'Sapphire', '1 L', 40, 'Inglaterra', 139.90, NULL, NULL, TRUE, 12, 0.145, 0.14, 'Dez botânicos infundidos no vapor durante a destilação. Floral, cítrico e muito equilibrado.', '["Floral","Cítrico","Infusão a vapor"]', 12),
  ('beefeater-pink', 'gin', 'Beefeater', 'Pink Strawberry', '750 ml', 37.5, 'Inglaterra', 109.90, 129.90, NULL, TRUE, 13, 0.163, 0.17, 'O London Dry da Beefeater com morango natural. Frutado e refrescante, sem perder o zimbro.', '["Morango","Frutado","Refrescante"]', 13),
  ('gordons', 'gin', 'Gordon''s', 'London Dry', '750 ml', 37.5, 'Reino Unido', 54.90, NULL, NULL, FALSE, 14, 0.164, 0.15, 'Receita de 1769, com zimbro em destaque e notas cítricas. Clássico, honesto e ótimo para o dia a dia.', '["Zimbro","Cítrico","Clássico"]', 14),
  ('eternity-melancia', 'gin', 'Eternity', 'Gin Melancia', '900 ml', 40, 'Brasil', 34.90, NULL, NULL, FALSE, 15, 0.094, 0.14, 'Gin doce sabor melancia. Leve e frutado, pronto para drinks com tônica ou soda e muito gelo.', '["Melancia","Doce","Frutado"]', 15),
  ('cachaca-51', 'cachaca', 'Cachaça 51', 'Pirassununga', '965 ml', 39, 'Brasil', 21.90, NULL, NULL, TRUE, 16, 0.168, 0.16, 'A cachaça mais vendida do mundo, de Pirassununga (SP). A base certa para uma boa caipirinha.', '["Caipirinha","Cana","Brasileira"]', 16),
  ('kit-jack-trio', 'kits', 'Jack Daniel''s', 'Família Jack Daniel''s', NULL, NULL, NULL, 379.90, NULL, 'Kit mais pedido', TRUE, NULL, NULL, NULL, 'Old No.7, Tennessee Apple e Tennessee Fire — o trio completo para provar lado a lado ou montar o bar.', '["Para presentear","Para o bar"]', 17),
  ('kit-tanqueray-3', 'kits', 'Tanqueray', 'Tanqueray 3 garrafas', NULL, NULL, NULL, 259.90, NULL, 'Leve 3, pague menos', FALSE, NULL, NULL, NULL, 'Três garrafas de Tanqueray London Dry para a festa não parar no gin tônica. Cada uma com o próprio lacre.', '["Gin tônica","Festa"]', 18),
  ('kit-gin-tour', 'kits', 'Seleção', 'Gin Tour', NULL, NULL, NULL, 314.90, NULL, 'Para provar', FALSE, NULL, NULL, NULL, 'Três estilos de gin: o seco Tanqueray, o floral Bombay Sapphire e o frutado Beefeater Pink.', '["Degustação","Gin tônica"]', 19),
  ('kit-whisky-classicos', 'kits', 'Seleção', 'Clássicos do Whisky', NULL, NULL, NULL, 209.90, NULL, 'Presente', FALSE, NULL, NULL, NULL, 'Escócia e Tennessee na mesma caixa: Johnnie Walker Black Label e Jack Daniel’s Old No.7.', '["Para presentear","Degustação"]', 20),
  ('kit-festa-vodka', 'kits', 'Seleção', 'Festa Vodka', NULL, NULL, NULL, 129.90, NULL, 'Para a festa', FALSE, NULL, NULL, NULL, 'Absolut, Smirnoff e Orloff: quase três litros de vodka para caipiroska, drinks e muito gelo.', '["Festa","Caipiroska"]', 21);

